    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // (1) out_both: both in[i] and its left neighbour (higher index) are 1
    // For bit i, left neighbour is in[i+1]; for i=3 there is no left neighbour
