module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding: 0 = idle (discarding), 1 = got byte 1, 2 = got byte 2, 3 = got byte 3
    reg [1:0] state, next_state;

    // Shift register to hold the last three valid bytes (byte1, byte2, byte3)
    reg [7:0] byte1, byte2, byte3;

    //----------------------------------------------------------------
    // Combinational logic: next-state generation and output logic
    //----------------------------------------------------------------
    always @(*) begin
        // Default assignments – ensures no latches are inferred
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            2'b00: begin // Idle – discard bytes until in[3] == 1
                if (in[3]) begin
                    next_state = 2'b01; // Assume this is byte 1
                    byte1      = in;
                end else begin
                    next_state = 2'b00;
                end
            end

            2'b01: begin // Received byte 1, now waiting for byte 2
                next_state = 2'b10;
                byte2      = in;
            end

            2'b10: begin // Received byte 2, now waiting for byte 3
                next_state = 2'b11;
                byte3      = in;

                // Third byte received – assert done and capture the message
                done       = 1'b1;
                out_bytes  = {byte1, byte2, byte3};
            end

            2'b11: begin // Should not stay in this state; reset after done
                // Immediately go back to idle for the next message
                next_state = 2'b00;
            end

            default: next_state = 2'b00;
        endcase
    end

    //----------------------------------------------------------------
    // Sequential logic: state and register updates on posedge clk
    //----------------------------------------------------------------
    always @(posedge clk) begin
        if (reset) begin
            state      <= 2'b00;
            byte1      <= 8'b0;
            byte2      <= 8'b0;
            byte3      <= 8'b0;
            done       <= 1'b0;
        end else begin
            state      <= next_state;
            done       <= 1'b0; // Clear done each cycle; the combinational block will re-assert it if we are transitioning from 10->11
            byte1 <= byte1; // keep values (they are only written on transitions in the comb block)
            byte2 <= byte2;
            byte3 <= byte3;
        end
    end

    //----------------------------------------------------------------
    // Output register: out_bytes is updated when done is asserted.
    // The spec says "out_bytes needs to be valid whenever the done signal
    // is asserted." Since done is pulsed high for one cycle, out_bytes
    // will be valid in that same cycle.
    //----------------------------------------------------------------
    always @(posedge clk) begin
        if (reset) begin
            out_bytes <= 24'b0;
        end else begin
            // out_bytes is updated whenever the FSM transitions into state 3
            // (i.e., after the third byte is latched). The combinational
            // block already computed out_bytes = {byte1,byte2,byte3} when
            // entering that state, and we also store it here so that it
            // remains valid as long as done is high (though done is only
            // high for one cycle per the spec).
            if (next_state == 2'b11) begin
                out_bytes <= {byte1, byte2, byte3};
            end
        end
    end

endmodule

