Prob139_2013_q2bfsm.code:
module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // ---------- FSM state encoding (one-hot) ----------
    // State A: 2'b01, State B: 2'b10, State C: 2'b00, State D: 2'b11
    reg [1:0] state;
    reg [1:0] next_state;

    // ---------- Outputs (Moore) ----------
    // f is 1 only in state B (the "one-cycle pulse" after reset deassertion)
    assign f = (state == 2'b10);

    // g is 1 in states B and C; 0 in state A and the unused state
    assign g = (state == 2'b10) || (state == 2'b00);

    // ---------- Combinational next-state logic ----------
    always @(*) begin
        case (state)
            2'b01: begin // State A
                // Stay in A as long as resetn is asserted (active-low)
                // When resetn is de-asserted, go to B after the clock edge
                if (!resetn)
                    next_state = 2'b10; // go to B
                else
                    next_state = 2'b01; // stay in A
            end
            2'b10: begin // State B
                // After one clock cycle in B, move to C
                next_state = 2'b00; // go to C
            end
            2'b00: begin // State C (monitor x for pattern 1,0,1)
                // Detect the pattern x = 1,0,1 over three cycles
                // The pattern is detected when the shift register has x3==1 && x2==0 && x1==1
                // On detection we go to D (2'b11) which keeps g=1 forever
                // Otherwise we stay in C and keep shifting
                if (x1 & ~x2 & x3)  // pattern detected
                    next_state = 2'b11; // go to D
                else
                    next_state = 2'b00; // stay in C
            end
            2'b11: begin // State D (g held permanently)
                // Stay in D forever while resetn is low
                next_state = 2'b11;
            end
            default: next_state = 2'b01;
        endcase
    end

    // ---------- Shift‑register for x (to detect 1,0,1) ----------
    // x1 is the oldest, x2 is the middle, x3 is the newest (current x)
    reg x1, x2, x3;
    always @(posedge clk) begin
        if (!resetn) begin
            x1 <= 1'b0;
            x2 <= 1'b0;
            x3 <= 1'b0;
        end else begin
            x1 <= x2;
            x2 <= x3;
            x3 <= x;
        end
    end

    // ---------- Registered next‑state update ----------
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b01; // reset to State A
            x1 <= 1'b0;
            x2 <= 1'b0;
            x3 <= 1'b0;
        end else begin
            state <= next_state;
            // shift register already updated above; keep it consistent
        end
    end

    // ---------- y‑monitor logic (Mealy‑like, but encoded in FSM) ----------
    // We need to know, while g=1 (in state C or D), whether y has appeared
    // within two clock cycles.  We keep a 2‑bit shift of y.
    reg y1, y2; // y1 = oldest, y2 = newest
    always @(posedge clk) begin
        if (!resetn) begin
            y1 <= 1'b0;
            y2 <= 1'b0;
        end else begin
            y1 <= y2;
            y2 <= y;
        end
    end

    // In state C we check: if y became 1 within the last two cycles,
    // we transition to D (g held permanently).  Otherwise we stay in C.
    // The detection is: y2 == 1 (y is 1 in the current cycle) OR
    // y1 == 1 (y was 1 one cycle ago).  If neither, we remain in C
    // and eventually g will be forced 0 after two cycles without y.
    always @(*) begin
        case (state)
            2'b00: begin // State C
                // If y has been 1 in the last two cycles, go to D
                if (y2 || y1)
                    next_state = 2'b11; // go to D
                else
                    next_state = 2'b00; // stay in C
            end
            2'b11: begin // State D (g held permanently)
                // Stay in D forever while resetn is low
                next_state = 2'b11;
            end
            default: next_state = 2'b01;
        endcase
    end

endmodule

