module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    // State encoding: A=2'b00, B=2'b01, C=2'b10, D=2'b11
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01,
        C = 2'b10,
        D = 2'b11
    } state_t;

    state_t state, next_state;

    // Combinational logic for next state and output
    always_comb begin
        case (state)
            A: begin
                next_state = in ? B : A;
                out        = 1'b0;
            end
            B: begin
                next_state = in ? C : B;   // explicit in-dependent assignment
                out        = 1'b0;
            end
            C: begin
                next_state = in ? D : A;
                out        = 1'b0;
            end
            D: begin
                next_state = in ? B : C;
                out        = 1'b1;
            end
            default: begin
                next_state = A;
                out        = 1'b0;
            end
        endcase
    end

    // Clocked state register with synchronous active-high reset
    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

