);

    // Internal state: 2-bit encoding for water level
    reg [1:0] state;
    reg [1:0] state_next;

    // Combinational logic for next state
    always @(*) begin
        case (state)
            2'b00: // Below s[0] (no sensors)
                if (s[0]) state_next = 2'b01; // Rising to between s[1] and s[0]
                else      state_next = 2'b00;
            2'b01: // Between s[1] and s[0] (s[0] asserted)
                if (s[1]) state_next = 2'b11; // Rising to between s[2] and s[1]
                else      state_next = 2'b00; // Falling to below s[0]
            2'b11: // Between s[2] and s[1] (s[1] asserted)
                if (s[2]) state_next = 2'b10; // Rising to above s[2]
                else      state_next = 2'b01; // Falling to between s[1] and s[0]
            2'b10: // Above s[2] (s[2] asserted)
                if (!s[2]) state_next = 2'b11; // Falling to between s[2] and s[1]
                else      state_next = 2'b10;
            default: state_next = 2'b00;
        endcase
    end

    // Sequential logic for state update
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;
        else
            state <= state_next;
    end

    // Output logic (Moore outputs based on state)
    // fr0: always on (except above s[2]? spec says above s[2] -> None, but below s[0] -> fr0,fr1,fr2)
    // Let's re-evaluate output assignments based on the truth table and spec description.
    // The spec says: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // This implies dfr is 1 when level rises.

    // Assigning outputs based on current state
    // State 00: Below s[0] -> fr0, fr1, fr2
    // State 01: Between s[1] and s[0] -> fr0, fr1 (from table: fr0, fr1)
    // State 11: Between s[2] and s[1] -> fr0 (from table: fr0)
    // State 10: Above s[2] -> None (fr0, fr1, fr2 all 0)

    // However, the spec mentions "the water level and the level previous to the last sensor change".
    // This suggests a Mealy element or additional state.
    // But the output table is purely based on current sensors and nominal inputs.
    // Let's stick to the table for primary outputs.
    // fr0 is always on except above s[2]?
    // Table: Above s[2] -> None. Between s[2] and s[1] -> fr0. Between s[1] and s[0] -> fr0, fr1. Below s[0] -> fr0, fr1, fr2.
    // So fr0 is on in all cases except Above s[2].
    // fr1 is on Between s[1] and s[0] and Below s[0].
    // fr2 is on Below s[0].

    // Let's assign based on state:
    // state 00 (Below s[0]): fr0=1, fr1=1, fr2=1
    // state 01 (Between s[1] and s[0]): fr0=1, fr1=1, fr2=0 (Table says fr0, fr1)
    // state 11 (Between s[2] and s[1]): fr0=1, fr1=0, fr2=0 (Table says fr0)
    // state 10 (Above s[2]): fr0=0, fr1=0, fr2=0

    assign fr0 = (state != 2'b10); // On unless above s[2]
    assign fr1 = (state == 2'b00) | (state == 2'b01); // On if below or between s1-s0
    assign fr2 = (state == 2'b00); // On only if below s[0]

    // dfr: Supplemental flow valve.
    // "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve"
    // This means dfr should be 1 when there is a rising edge in level.
    // We need to detect rising edge.
    // prev_state tracks the level before the current one.
    // Or we can infer from state transition.
    // If state_next > state (in terms of level), then rising.
    // Levels: 00 (lowest), 01, 11, 10 (highest).
    // Rising edge: 00->01, 01->11, 11->10.
    // Falling: 10->11, 11->01, 01->00.

    // Let's register previous state to detect edges.
    reg [1:0] prev_state;
    always @(posedge clk) begin
        if (reset)
            prev_state <= 2'b00;
        else
            prev_state <= state;
    end

    // dfr is 1 if rising edge detected
    // Rising: prev_state = 00 and state = 01
    //         prev_state = 01 and state = 11
    //         prev_state = 11 and state = 10
    assign dfr = ((prev_state == 2'b00) & (state == 2'b01)) |
                 ((prev_state == 2'b01) & (state == 2'b11)) |
                 ((prev_state == 2'b11) & (state == 2'b10));

    // Synchronous reset description: "resets the state machine to a state equivalent to if the water level had been low for a long time (no sensors asserted, and all four outputs asserted)."
    // This means reset sets state to 00 (below s[0]), and outputs fr0,fr1,fr2, dfr to their "low level" values.
    // Our reset block sets state <= 00.
    // Outputs are continuous assignments, so they will reflect state 00 immediately after reset (or next cycle).
    // dfr logic uses prev_state. On reset, prev_state is also reset to 00.
    // This seems consistent.

endmodule

