module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD display
);

    // Internal state: 4 BCD digits (ones, tens, hundreds, thousands)
    // We use 5 bits per digit to allow a simple wrap-around check at 10 (1010 binary).
    // This avoids a separate BCD-to-binary converter for the increment logic.
    reg [19:0] count;   // count[4:0] = ones, count[9:5] = tens, count[14:10] = hundreds, count[19:15] = thousands

    // Wire for the enable signals (one per upper digit)
    wire ena_tens;   // enable for tens digit (q[7:4])
    wire ena_hunds;  // enable for hundreds digit (q[11:8])
    wire ena_thous;  // enable for thousands digit (q[15:12])

    // ------------------------------------------------------------
    // Combinational logic: BCD increment & enable generation
    // ------------------------------------------------------------

    // We compute the next count value here. Because the counter wraps
    // at 10 per digit, we need to detect when a digit is 9 (1010) and
    // produce a carry to the next digit.
    //
    // Let the internal 20-bit value be:
    //   [4:0]  ones
    //   [9:5]  tens
    //   [14:10] hundreds
    //   [19:15] thousands
    //
    // For each digit position, if the digit is 9 (i.e. bits are 1010),
    // the next digit gets incremented and this digit becomes 0.
    // If the digit is not 9, it simply increments by 1 and no carry
    // is generated.

    // --- Ones digit (always increments, wraps at 10) ---
    wire [4:0] ones_next;
    wire ones_carry;   // carry to tens when ones goes 9 -> 0

    // ones_next = (count[4:0] == 5'd9) ? 5'd0 : count[4:0] + 1'b1;
    assign ones_next = (count[4:0] == 5'd9) ? 5'd0 : count[4:0] + 1'b1;
    assign ones_carry = (count[4:0] == 5'd9);   // carry occurs exactly at 9

    // --- Tens digit ---
    wire [4:0] tens_next;
    wire tens_carry;

    assign tens_next = (count[9:5] == 5'd9) ? 5'd0 : count[9:5] + ones_carry;
    assign tens_carry = (count[9:5] == 5'd9);   // carry to hundreds when tens was 9

    // --- Hundreds digit ---
    wire [4:0] hunds_next;
    wire hunds_carry;

    assign hunds_next = (count[14:10] == 5'd9) ? 5'd0 : count[14:10] + tens_carry;
    assign hunds_carry = (count[14:10] == 5'd9);   // carry to thousands when hundreds was 9

    // --- Thousands digit ---
    wire [4:0] thous_next;

    // Thousands wraps at 10 as well, but we keep it within 5 bits.
    // If it reaches 9, it goes to 0; no higher digit exists.
    assign thous_next = (count[19:15] == 5'd9) ? 5'd0 : count[19:15] + hunds_carry;

    // --- Enable signals ---
    // ena_tens   is set when the ones digit rolled over (9 -> 0)
    // ena_hunds  is set when the tens digit rolled over
    // ena_thours is set when the hundreds digit rolled over
    assign ena_tens   = ones_carry;
    assign ena_hunds  = tens_carry;
    assign ena_thous  = hunds_carry;

    // ------------------------------------------------------------
    // Sequential logic: state update on posedge clk
    // ------------------------------------------------------------

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous active-high reset: initialise all digits to 0
            count <= 20'd0;
        end else begin
            count <= {thous_next, hunds_next, tens_next, ones_next};
        end
    end

    // ------------------------------------------------------------
    // Assign module ports
    // ------------------------------------------------------------

    // ena is a 3-bit output: [2] = thousands enable, [1] = hundreds enable, [0] = tens enable
    // The specification says "output ena (3 bits)" and "indicating when each of the upper three digits
    // should be incremented".  We map the enables as:
    //   ena[2] -> thousands (q[15:12])
    //   ena[1] -> hundreds   (q[11:8])
    //   ena[0] -> tens       (q[7:4])
    // The ones digit has no enable output because it is the least‑significant digit.
    assign ena = {ena_thous, ena_hunds, ena_tens};

    // q is the 16‑bit BCD display: q[3:0] ones, q[7:4] tens, q[11:8] hundreds, q[15:12] thousands
    // We only need the lower 16 bits of the 20‑bit internal counter.
    assign q = count[15:0];

endmodule

