module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 00=walk_left, 01=walk_right, 10=falling, 11=digging
    reg [1:0] state, next_state;
    reg [4:0] fall_counter, next_fall_counter;
    reg splatter;

    // Outputs (Moore)
    assign walk_left  = (state == 2'b00);
    assign walk_right = (state == 2'b01);
    assign aaah       = (state == 2'b10);
    assign digging    = (state == 2'b11);

    // State register (positive edge triggered, async reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= 2'b00;
            fall_counter <= 5'd0;
            splatter     <= 1'b0;
        end else begin
            state       <= next_state;
            fall_counter <= next_fall_counter;
            splatter     <= 1'b0; // cleared each cycle; set only on splatter condition
        end
    end

    // Next-state logic (combinational)
    always @(*) begin
        next_state = state;
        next_fall_counter = fall_counter;

        // Default: no change
        // Priority: fall > dig > switch direction

        case (state)
            2'b00: begin // walking left
                if (!ground) begin
                    // Fall starts
                    next_state = 2'b10;
                    next_fall_counter = 5'd1;
                end else if (dig & !splatter) begin
                    // Start digging (but fall has higher precedence, checked above)
                    // Since fall condition was false, we are on ground
                    next_state = 2'b11;
                end else if (bump_left | bump_right) begin
                    // Switch direction
                    if (bump_left & !bump_right)
                        next_state = 2'b01; // walk right
                    else if (bump_right & !bump_left)
                        next_state = 2'b00; // walk left
                    else
                        next_state = 2'b01; // bumped both sides, switch to right
                end
                // else stay walking left
            end

            2'b01: begin // walking right
                if (!ground) begin
                    next_state = 2'b10;
                    next_fall_counter = 5'd1;
                end else if (dig & !splatter) begin
                    next_state = 2'b11;
                end else if (bump_left | bump_right) begin
                    if (bump_left & !bump_right)
                        next_state = 2'b00; // walk left
                    else if (bump_right & !bump_left)
                        next_state = 2'b11; // walk right? wait, bump right -> walk left
                    else
                        next_state = 2'b00; // both sides
                end
                // else stay walking right
            end

            2'b10: begin // falling
                // Increment fall counter
                if (fall_counter < 5'd20)
                    next_fall_counter = fall_counter + 1'b1;
                else
                    next_fall_counter = 5'd20;

                // Check ground reappearance
                if (ground) begin
                    // Hit ground
                    if (fall_counter >= 5'd20) begin
                        // Splatter
                        next_state = 2'b00; // or keep splatter state? spec says cease all outputs forever.
                        // We'll stay in a splatter state; use state 00 but with splatter flag.
                        // To properly cease all outputs, we need a dedicated splatter state or use the flag.
                        // Since outputs are derived from state only (Moore), we need a state where all outputs are 0.
                        // Let's use state 2'b11? No, digging.
                        // We need a state where walk_left=0, walk_right=0, aaah=0, digging=0.
                        // Currently state 00 gives walk_left=1. So we need a new state or use splatter flag.
                        // The spec says "all 4 outputs become 0, forever".
