                end
            end

            2'b11: begin // digging
                if (!ground) begin
                    // Hit ground while digging? spec: "will continue digging until it reaches the other side (ground=0). At that point, since there is no ground, it will fall (aaah!), then continue walking in its original direction once it hits ground again."
                    // So if digging and ground becomes 0, fall starts.
                    next_state = 2'b10;
                    next_fall_counter = 5'd1;
                end else begin
                    // Still digging, check if told to stop? dig input might change.
                    // "A Lemming can dig if it is currently walking on ground (ground=1 and not falling), and will continue digging until it reaches the other side (ground=0)."
                    // So if dig=1 and ground=1, stay digging.
